  function taskGroups(tasks){if(wardFilter!=='all')return tasks.map(wardTaskCard).join('');const completed=tasks.filter(t=>['done','omitted','cancelled'].includes(t.status)),open=tasks.filter(t=>!completed.includes(t));return open.map(wardTaskCard).join('')+(completed.length?'<details class="cl-completed"><summary>완료·미실시·중단 '+completed.length+'건</summary>'+completed.map(wardTaskCard).join('')+'</details>':'');}
  function attentionSummary(items,board=false){const now=Date.now();let late=0,held=0,reviews=0,checks=0,handoffs=0;for(const item of items){const b=item.body||{},d=wardDue(b.tasks||[],now);late+=d.late;held+=d.held;reviews+=(b.tasks||[]).filter(t=>t.reassessment&&!t.reassessment.completedAt&&Date.parse(t.reassessment.plannedAt)<=now).length;checks+=(b.wardChecks||[]).filter(c=>!c.closedAt&&Date.parse(c.plannedAt)<=now).length;handoffs+=b.lastHandoff&&!b.lastHandoff.ackAt?1:0;}return '<section class="cl-attention" aria-label="지금 확인할 일"><b>지금 확인할 일</b><div>'+[[late+held,'지연 '+late+' · 보류 '+held,board?'attention-work':'tasks'],[reviews,'재평가 '+reviews,board?'attention-work':'tasks'],[checks,'검사·기구 확인 '+checks,board?'attention-work':'measure'],[handoffs,'인수 대기 '+handoffs,board?'attention-handoff':'handoff']].map(([n,l,k])=>button('ward-attention',l,'data-id="'+(board?k:'patient-'+k)+'" class="'+(n?'cl-attention-needed':'')+'"')).join('')+'</div></section>';}
  function wardTimeline(){const b=active().body,tasks=wardTaskList(b.tasks||[],wardDate,wardFilter,wardStaff),due=wardDue(b.tasks||[]);return '<div class="cl-toolbar"><div><b>지연 '+due.late+' · 보류 '+due.held+'</b><p>다음 처치 '+(due.next?esc(due.next.title)+' · '+fmtDate(due.next.plannedAt):'없음')+'</p></div><div class="cl-actions">'+(medical()&&active().status!=='closed'?button('eff-sets','처치 세트')+button('ward-medication','투약 지시')+button('ward-order','기타 처치','data-kind="other"'):'')+(detail.canRecord&&active().status!=='closed'?button('eff-round','회진 통합 기록')+button('eff-batch','처치 모아 기록'):'')+'</div></div>'+(efficiency?.notices()||'')+'<div class="cl-filters">'+input('wardDate',wardDate===wardDay()?'업무일 · 오늘':'업무일 · 이전/다른 날짜 조회 중',wardDate,'date')+select('wardStaff','담당자',[['','전체 직원'],...members.map(m=>[m.id||m.user_id,m.display_name||m.name])],wardStaff)+select('wardFilter','상태',[['all','전체 · 이전 미완료 포함'],['planned','예정'],['late','지연 · 이전 날짜 포함'],['held','보류'],['done','완료'],['omitted','미실시'],['cancelled','중단']],wardFilter)+'</div>'+(carry?.rows&&sameCase(active(),carry.patient)?'<section class="cl-card"><b>계산기 결과에서 투약 지시 만들기</b><div class="cl-actions">'+carry.rows.map((r,i)=>button('ward-import',esc(r.drug),'data-id="'+i+'"')).join('')+'</div><small>환자·용량·경로를 대조하고 첫 투여 시각을 확인한 뒤 저장합니다.</small></section>':'')+wardPendingChecks()+'<div class="cl-tasks">'+taskGroups(tasks)+(tasks.length?'':'<p class="cl-empty">선택한 조건의 처치가 없습니다.</p>')+'</div>';}
  function wardTaskCard(t){const state=taskState(t),m=t.medication,record=detail.canRecord&&active().status!=='closed',open=['planned','held'].includes(t.status);return '<article data-cl-task-id="'+esc(t.id)+'" class="cl-task cl-state-'+state+'"><div><b>'+esc(t.title)+'</b><span>'+fmtDate(t.plannedAt)+' · '+(m?.prn&&!t.prnOrderId?'PRN':statusNames[state])+' · '+esc(t.assigneeId?memberName(t.assigneeId):'담당 미지정')+'</span></div>'+(m?'<p class="cl-med-dose"><b>'+num(m.amount)+' '+esc(m.amountUnit)+'</b> · '+num(m.dose)+' '+esc(m.doseUnit)+' · '+esc(m.route)+(t.intervalHours?' · '+t.intervalHours+'시간 간격':'')+'<small>함량 '+num(m.strength)+' '+esc(m.strengthUnit)+'/'+esc(m.amountUnit)+'</small></p>'+(m.prn?'<p>PRN · 최소 '+m.minIntervalHours+'시간 · '+esc(m.indication)+'</p>'+(!t.prnOrderId?'<p class="cl-prn-status">최근 투여 '+fmtDate(wardPrn(active().body.tasks,t).last)+' · 다음 가능 '+fmtDate(wardPrn(active().body.tasks,t).next)+'</p>':''):''):'')+'<p>'+esc(t.instruction)+'</p>'+(t.actualAt?'<small>실제 '+fmtDate(t.actualAt)+' · '+esc(t.recorder?.name||memberName(t.recordedBy)||'미기록')+' · '+esc(t.note)+'</small>':'')+(t.reassessment?'<p class="'+(!t.reassessment.completedAt&&Date.parse(t.reassessment.plannedAt)<Date.now()?'cl-alert':'')+'">재평가 '+fmtDate(t.reassessment.plannedAt)+' · '+esc(memberName(t.reassessment.assigneeId)||'담당 미지정')+' · '+(t.reassessment.completedAt?'완료 '+fmtDate(t.reassessment.completedAt)+' · '+esc(t.reassessment.result):'대기')+'</p>':'')+(t.responses||[]).map(r=>'<p>반응 '+fmtDate(r.at)+' · '+esc(r.note)+'</p>').join('')+'<div class="cl-actions">'+(record&&open?button(m?.prn?'ward-prn':'task',m?.prn?'PRN 투여 기록':'수행 기록','data-id="'+t.id+'"'):'')+(record&&t.status==='done'?button('ward-response','반응 기록','data-id="'+t.id+'"')+(!t.reassessment?button('ward-reassess','재평가 예약','data-id="'+t.id+'"'):!t.reassessment.completedAt?button('ward-reassess-done','재평가 완료','data-id="'+t.id+'"'):''):'')+(medical()&&open&&active().status!=='closed'?button('ward-change','남은 지시 변경','data-id="'+t.id+'"'):'')+'</div></article>';}
  function wardMeasurements(){const b=active().body,record=detail.canRecord&&active().status!=='closed';return '<section class="cl-card"><div class="cl-toolbar"><h4>체중·체온·심박수·호흡</h4><div class="cl-actions">'+(record?button('eff-round','회진 통합 기록')+button('ward-vitals','측정 기록')+button('ward-pain','통증·호흡 평가'):'')+(medical()&&wardVitals(b).weightKG&&active().status!=='closed'?button('ward-weight','측정 체중을 계산에 사용'):'')+'</div></div>'+wardVitalCards(b)+'<small>각 항목의 마지막 측정값입니다. 미측정 항목을 정상으로 판단하지 않습니다.</small></section><section class="cl-card"><div class="cl-toolbar"><h4>생활 모니터링</h4>'+(record?button('ward-monitor','관찰 기록'):'')+'</div><div class="cl-monitor-grid">'+monitoringMarkup(b.latestMonitoring)+'</div><small>'+fmtDate(b.latestMonitoring?.observedAt)+' · 기록자 '+esc(recorderName(b.latestMonitoring))+'</small></section>'+(b.latestPain?'<section class="cl-card"><h4>최근 통증·호흡 평가</h4><p>'+esc(b.latestPain.scale)+' · '+b.latestPain.score+'/'+b.latestPain.max+' · '+fmtDate(b.latestPain.observedAt)+' · '+esc(recorderName(b.latestPain))+'</p><p>호흡 '+({unknown:'미확인',comfortable:'편안함',effort:'노력성',distress:'곤란'})[b.latestPain.respiration]+' · '+esc(b.latestPain.note)+'</p></section>':'')+'<details class="cl-card"><summary>측정 추이 · 최근 80회</summary><div class="cl-table-scroll"><table><thead><tr><th>측정</th>'+['weightKG','temperature','heartRate','respiratoryRate','spo2','systolic'].map(k=>'<th>'+vitalLabels[k]+'</th>').join('')+'<th>기록자</th></tr></thead><tbody>'+(b.wardTrend||[]).filter(r=>['weightKG','temperature','heartRate','respiratoryRate','spo2','systolic'].some(k=>r.values[k]!=null)).slice().sort((a,b)=>Date.parse(b.observedAt)-Date.parse(a.observedAt)).map(r=>'<tr><td>'+fmtDate(r.observedAt)+'</td>'+['weightKG','temperature','heartRate','respiratoryRate','spo2','systolic'].map(k=>'<td>'+esc(r.values[k]??'—')+'</td>').join('')+'<td>'+esc(recorderName(r))+'</td></tr>').join('')+'</tbody></table></div></details>';}
  function wardFluids(){const b=active().body,start=ioFrom?iso(ioFrom):wardDate+'T00:00:00+09:00',end=ioTo?iso(ioTo):new Date(Date.parse(start)+86400000).toISOString(),sum=wardTotals(b,start,end),labels={iv:'수액',cri:'CRI',water:'음수',food:'급여',urine:'소변'};return '<div class="cl-toolbar"><h4>수액·급여·배설</h4><div class="cl-actions">'+(active().status!=='closed'?(medical()?button('ward-infusion','수액·CRI 계획')+button('ward-feed-order','급여 지시'):'')+(detail.canRecord?button('ward-io','실측량 기록'):''):'')+'</div></div>'+'<h4>현재 주입 설정</h4>'+(b.infusions||[]).filter(r=>!r.endedAt).map(r=>{const st=infusionStatus(r),replace=st.replaceAt;return '<section class="cl-card"><b>'+esc(r.name)+' · '+num(r.rate)+' mL/hr</b><p>'+esc(r.additive)+'</p><p>시작 '+fmtDate(r.startAt)+' · 총 '+num(r.volume)+' mL · '+(st.paused?'일시중단': '예상 소진 '+fmtDate(replace))+'</p><p>추정 잔량 '+num(st.remaining)+' mL'+(st.check?' · 실측 '+num(st.check.remaining)+' mL ('+fmtDate(st.check.at)+')':' · 실측 잔량 미기록')+'</p><div class="cl-actions">'+(detail.canRecord?button('ward-infusion-state',st.paused?'주입 재개':'일시중단','data-id="'+r.id+'" data-mode="'+(st.paused?'resume':'pause')+'"')+button('ward-infusion-state','잔량 확인','data-id="'+r.id+'" data-mode="remaining"'):'')+(medical()?button('ward-infusion','속도 변경','data-id="'+r.id+'" data-mode="rate"')+button('ward-infusion','백·시린지 교체','data-id="'+r.id+'" data-mode="replace"')+button('ward-infusion-end','주입 종료','data-id="'+r.id+'"'):'')+'</div></section>';}).join('')+'<section class="cl-card cl-io-summary"><h4>선택 구간의 실측 섭취·배설량</h4>'+input('wardDate','집계일 · 한국 시간',wardDate,'date')+'<div class="cl-form-grid">'+input('ioFrom','구간 시작',ioFrom||wardDate+'T00:00','datetime-local')+input('ioTo','구간 종료',ioTo||new Date(Date.parse(end)+32400000).toISOString().slice(0,16),'datetime-local')+'</div><div class="cl-actions">'+button('io-range','구간 적용')+button('io-day','선택한 날짜 하루 보기')+'</div><p>'+fmtDate(start)+' ~ '+fmtDate(end)+'</p>'+'<div class="cl-io-totals">'+Object.entries(sum.totals).map(([k,v])=>{const [type,unit]=k.split(':');return '<b>'+labels[type]+' 실측 '+num(v)+' '+unit+'</b>';}).join('')+'</div><p>계획 속도 기준 주입 추정 '+num(sum.estimated)+' mL · 실측량과 합산하지 않음</p>'+(sum.partial.length?'<p class="cl-stale">날짜 경계를 걸친 '+sum.partial.length+'개 실측 기록은 배분하지 않았습니다. 아래 구간을 확인하세요.</p>':'')+'</section>'+'<details class="cl-card"><summary>주입 변경·중단·잔량 이력</summary>'+(b.infusions||[]).slice().reverse().map(r=>'<p><b>'+esc(r.name)+'</b> '+num(r.rate)+' mL/hr · '+fmtDate(r.startAt)+(r.endedAt?' ~ '+fmtDate(r.endedAt):'')+'</p>'+(r.execution||[]).map(e=>'<p>'+fmtDate(e.at)+' · '+({pause:'중단',resume:'재개',remaining:'실측 잔량 '+num(e.remaining)+' mL'})[e.action]+' · '+esc(e.note)+'</p>').join('')).join('')+'</details><details class="cl-card"><summary>실측량 기록</summary>'+(b.wardIO||[]).slice().reverse().map(r=>'<p>'+labels[r.type]+' '+num(r.amount)+' '+r.unit+' · '+fmtDate(r.periodStart)+' ~ '+fmtDate(r.observedAt)+' · '+esc(r.note)+'</p>').join('')+'</details>'+(b.tasks||[]).filter(t=>t.category==='diet').map(wardTaskCard).join('');}
  function wardHandoff(){const b=active().body,h=b.lastHandoff;return '<section class="cl-card"><div class="cl-toolbar"><h4>교대 인계</h4>'+(detail.canRecord&&active().status!=='closed'?button('handoff','새 인계 작성'):'')+'</div>'+(h?'<p>인계 '+fmtDate(h.at)+' · '+esc(h.recorder?.name||memberName(h.by))+' → '+esc(memberName(h.recipientId))+'</p><b>'+(h.ackAt?'확인 완료 · '+fmtDate(h.ackAt):'인수 확인 대기')+'</b><p class="cl-handoff-note">'+esc(h.note)+'</p><p>검사 대기: '+esc(h.snapshot?.precautions?.pendingTests||'미기록')+' · 다음 확인: '+esc(h.snapshot?.precautions?.nextReview||'미기록')+'</p><p>인계 당시 미완료 '+h.pendingTaskIds.length+'개</p><div class="cl-handoff-list">'+h.pendingTaskIds.filter(id=>!['done','omitted','cancelled'].includes((b.tasks||[]).find(t=>t.id===id)?.status)).map(id=>{const t=(b.tasks||[]).find(t=>t.id===id);return '<p><b>'+esc(t?.title||'기존 처치')+'</b> · 인계 당시 미완료 → 현재 '+esc(t?statusNames[taskState(t)]:'기록 확인 필요')+(t?.actualAt?' · '+fmtDate(t.actualAt):'')+(t?.cancelledAt?' · 중단 '+fmtDate(t.cancelledAt):'')+'</p>';}).join('')+'</div><details><summary>인계 후 완료·미실시·중단된 처치</summary>'+h.pendingTaskIds.filter(id=>['done','omitted','cancelled'].includes((b.tasks||[]).find(t=>t.id===id)?.status)).map(id=>{const t=b.tasks.find(t=>t.id===id);return '<p>'+esc(t.title)+' · '+esc(statusNames[t.status])+' · '+fmtDate(t.actualAt||t.cancelledAt)+'</p>';}).join('')+'</details>'+(!h.ackAt&&detail.canRecord?button('ward-ack','내 계정으로 인계 확인'):''):'<p>인계 기록이 없습니다.</p>')+'</section>'+history();}
  function wardNewPatient(){const b=active().body;return '<section class="cl-ward-patient"><div class="cl-patient-sticky"><div class="cl-patient-summary"><h3>'+esc(active().patient.name)+'</h3><span>'+weightSummary(b)+'</span></div>'+careTeamMarkup(b.careTeam)+wardPrecautions(b,true)+'<details class="cl-patient-manage"><summary>환자·입원 관리</summary>'+identityCard(active())+'<div class="cl-actions">'+(medical()&&active().status!=='closed'?button('ward-plan','주의사항·보고 기준')+button('ward-move','입원실 이동'):'')+'</div></details><nav class="cl-tabs cl-ward-tabs">'+[['tasks','처치 일정'],['measure','측정·관찰'],['fluids','수액·급여'],['handoff','인계·기록']].map(([k,l])=>button('ward-tab',l,'data-id="'+k+'" aria-pressed="'+(wardTab===k)+'"')).join('')+'</nav></div><p class="cl-background" role="status">'+esc(backgroundMessage||'서버 확인 '+fmtDate(loadedAt||null))+'</p>'+attentionSummary([active()])+(wardTab==='tasks'?wardTimeline():wardTab==='measure'?'<div class="cl-measure-layout">'+wardMeasurements()+wardCheckPanel()+'</div>':wardTab==='fluids'?wardFluids():wardHandoff())+'</section>';}
  function wardMedFields(m={}){return '<div class="cl-form-grid">'+input('drug','성분·약물명',m.drug||'')+input('dose','1회 총 약물량 · 체중당 값 아님',m.dose??'','number')+select('doseUnit','약물량 단위',[['mg','mg'],['mcg','mcg'],['IU','IU'],['mEq','mEq'],['unit','제품 단위']],m.doseUnit||'mg')+input('strength','제품 함량 · 1정/1캡슐/1mL당',m.strength??'','number')+select('strengthUnit','함량 단위',[['mg','mg'],['mcg','mcg'],['IU','IU'],['mEq','mEq'],['unit','제품 단위']],m.strengthUnit||'mg')+select('amountUnit','투여 단위',[['mL','mL'],['정','정'],['캡슐','캡슐']],m.amountUnit||'mL')+select('route','투여 경로',[['','경로 선택'],['PO','경구'],['IV','정맥'],['IM','근육'],['SC','피하'],['other','기타 · 지시에 기재']],m.route||'')+input('amount','1회 투여량 · 자동 환산',m.amount??'','number')+'</div><label><input type="checkbox" name="prn" '+(m.prn?'checked':'')+'>필요 시 투여 · PRN</label><div class="cl-form-grid" data-prn-fields '+(m.prn?'':'hidden')+'>'+input('minIntervalHours','PRN 최소 투여 간격 · 시간',m.minIntervalHours||'','number')+input('indication','PRN 투여 조건',m.indication||'')+'</div>';}
  function wardMedRead(f){const v=formValues(f);return {drug:v.drug,dose:Number(v.dose),doseUnit:v.doseUnit,strength:Number(v.strength),strengthUnit:v.strengthUnit,amount:Number(v.amount),amountUnit:v.amountUnit,route:v.route,prn:f.elements.prn.checked,minIntervalHours:Number(v.minIntervalHours),indication:v.indication};}
  function wardBindMed(){const f=dialog.querySelector('form');dialog.classList.add('cl-medication-dialog');const template=f.querySelector('[data-ward-template]');if(template){const box=document.createElement('details');box.className='cl-template-picker';box.innerHTML='<summary>병원 공통 처치 서식</summary>';template.closest('label').before(box);box.append(template.closest('label'));for(const key of ['data-ward-template-use','data-ward-template-delete']){const b=f.querySelector('['+key+']');if(b)box.append(b);}}f.elements.amount.readOnly=true;const update=()=>{f.querySelector('[data-prn-fields]').hidden=!f.elements.prn.checked;const d=Number(f.elements.dose.value),s=Number(f.elements.strength.value),du=f.elements.doseUnit.value,su=f.elements.strengthUnit.value;f.elements.amount.value=d>0&&s>0&&(du===su||['mg','mcg'].includes(du)&&['mg','mcg'].includes(su))?String(d*(du==='mcg'?.001:1)/(s*(su==='mcg'?.001:1))):'';};f.addEventListener('input',update);f.addEventListener('change',update);update();}
  function wardOrderForm(seed={},task=null){const m=seed.medication||task?.medication||{};modal(task?'남은 투약 지시 변경':'투약 지시',(seed.context?'<p class="cl-stale">'+esc(seed.context)+'</p>':'')+(!task?wardDrugPicker():'')+wardMedFields(m)+(!task?wardStrengthEditor():'')+input(task?'effectiveAt':'plannedAt',task?'변경 적용 시각 · 이후 남은 일정만':'첫 투여 시각 · 한국 시간',localTime(),'datetime-local')+area('instruction',task?'변경 내용·중단 사유':'확정 지시·주의사항',task?.instruction||'')+(!task?select('assigneeId','담당 직원',[['','미지정'],...members.map(m=>[m.id||m.user_id,m.display_name||m.name])])+'<div class="cl-form-grid">'+input('repeatCount','총 횟수',seed.count||1,'number')+input('intervalHours','간격 · 시간',seed.interval||0,'number')+'</div><details><summary>현재 입력을 병원 공통 처치 서식으로 저장</summary>'+input('templateTitle','서식 이름')+'<label><input type="checkbox" name="templateConfirm">환자 식별정보 없이 공통으로 쓸 용량·함량·지시임을 확인했습니다.</label><button type="button" data-ward-template-save>공통 서식 저장</button></details>':'<label><input type="checkbox" name="cancel">이 시각 이후 남은 지시 중단</label>')+'<label><input type="checkbox" name="confirm" required>환자·약물·제품 함량·투여량·경로·일정을 대조했습니다.</label>',f=>{const v=formValues(f),medication=wardMedRead(f);return task?event('order.change',{taskId:task.id,effectiveAt:iso(v.effectiveAt),title:medication.drug,instruction:v.instruction,medication,cancel:f.elements.cancel.checked,confirm:true}):event('order.add',{title:medication.drug,category:medication.route==='PO'?'medication':'injection',plannedAt:iso(v.plannedAt),instruction:v.instruction,assigneeId:v.assigneeId,repeatCount:medication.prn?1:Number(v.repeatCount),intervalHours:medication.prn?0:Number(v.intervalHours),medication,confirm:true,...efficiency?.scheduleData(f)});});wardBindMed();if(task)efficiency?.changePreview(dialog.querySelector('form'),task);else{efficiency?.schedule(dialog.querySelector('form'));void wardBindPicker();}}
  function wardPendingChecks(){const b=active().body,checks=(b.wardChecks||[]).filter(x=>!x.closedAt),reviews=(b.tasks||[]).filter(t=>t.reassessment&&!t.reassessment.completedAt);return (checks.length||reviews.length)?'<section class="cl-card cl-pending-checks"><b>검사·기구 확인 '+checks.length+'개 · 재평가 '+reviews.length+'개</b>'+reviews.map(t=>'<p class="'+(Date.parse(t.reassessment.plannedAt)<Date.now()?'cl-alert':'')+'">'+fmtDate(t.reassessment.plannedAt)+' · '+esc(t.title)+' '+button('ward-reassess-done','재평가 완료','data-id="'+t.id+'"')+'</p>').join('')+button('ward-tab','검사·기구 보기','data-id="measure"')+'</section>':'';}
