  function wardHospitalTimeline(){let entries=[];for(const r of rooms){const c=r.patientCase;if(!c?.body||c.status==='closed')continue;const b=c.body,abnormal=Object.keys(monitoringLabels).some(k=>monitoringTone(k,b.latestMonitoring?.[k])==='abnormal')||Object.keys(vitalLabels).some(k=>wardVitalStatus(b,k).abnormal),unack=b.lastHandoff&&!b.lastHandoff.ackAt;if(boardFilter==='abnormal'&&!abnormal||boardFilter==='handoff'&&!unack)continue;
   const ts=wardTaskList(b.tasks||[],wardDate,boardFilter==='late'?'late':'all',boardFilter==='mine'?(performerId||userId):'').filter(t=>boardFilter!=='attention'||taskState(t)==='late'||t.status==='held');for(const t of ts)entries.push({room:r,target:t.id,targetKind:'task',title:t.title,at:t.plannedAt,state:t.medication?.prn&&!t.prnOrderId?'PRN':statusNames[taskState(t)],assignee:t.assigneeId,rank:['done','omitted','cancelled'].includes(t.status)?4:taskState(t)==='late'||t.status==='held'?0:1});
   const auxiliary=[...(b.wardChecks||[]).filter(x=>!x.closedAt).map(x=>({...x,targetKind:'check',title:(x.type==='test'?'검사: ':'기구: ')+x.title})),...(b.tasks||[]).filter(t=>t.reassessment&&!t.reassessment.completedAt).map(t=>({...t.reassessment,id:t.id,targetKind:'review',title:'재평가: '+t.title}))];
   for(const x of auxiliary){const late=Date.parse(x.plannedAt)<Date.now();if(boardFilter==='mine'&&x.assigneeId!==(performerId||userId)||['late','attention'].includes(boardFilter)&&!late)continue;if(wardDay(x.plannedAt)!==wardDate&&!(wardDate===wardDay()&&late))continue;entries.push({room:r,target:x.id,targetKind:x.targetKind,title:x.title,at:x.plannedAt,state:late?'확인 지연':'확인 예정',assignee:x.assigneeId,rank:late?0:1});}
   if(!ts.length&&!auxiliary.length&&['abnormal','handoff'].includes(boardFilter))entries.push({room:r,title:boardFilter==='abnormal'?'관찰 이상소견 확인':'인수 확인 대기',at:'',state:'확인 필요',rank:0});
  }entries.sort((a,b)=>a.rank-b.rank||Date.parse(a.at)-Date.parse(b.at));return '<div class="cl-filters">'+input('boardDate','업무일',wardDate,'date')+select('boardFilter','보기',[['all','전체 · 이전 미완료 포함'],['attention','지금 확인할 일'],['mine','내 담당 처치'],['late','지연'],['abnormal','이상소견 환자'],['handoff','인수 확인 대기']],boardFilter)+'</div><div class="cl-hospital-timeline">'+entries.map(x=>'<div class="cl-schedule-entry"><button class="cl-schedule-row '+(x.rank===0?'cl-schedule-late':'')+'" data-cl-action="room-open" data-id="'+esc(x.room.id)+'" data-target="'+esc(x.target||'')+'" data-target-kind="'+esc(x.targetKind||'')+'"><span><b>'+esc(x.room.patientCase.patient?.name)+'</b><small>'+esc(x.room.name)+'</small></span><span>'+esc(x.title)+'<small>'+(g.ClinicalEfficiency?.relativeTime(x.at)||fmtDate(x.at))+' · '+esc(memberName(x.assignee)||'담당 미지정')+'</small></span><strong>'+esc(x.state)+'</strong></button>'+((x.targetKind==='task'&&x.rank!==4&&a.can?.('records.edit')!==false)?button('quick-record','수행 기록','data-id="'+esc(x.room.id)+'" data-target="'+esc(x.target)+'" aria-label="'+esc(x.room.patientCase.patient?.name+' · '+x.title+' 수행 기록')+'"'):'')+'</div>').join('')+(entries.length?'':'<p class="cl-empty">선택한 조건의 처치·확인 항목이 없습니다.</p>')+'</div>';}
