    f.elements.amountUnit.value=p.manual?'':({tablet:'정',capsule:'캡슐',liquid:'mL'})[v.kind];f.elements.route.value=meta.route==='oral'?'PO':prep?.injectionRoute||meta.injectionRoute||'';
    if(!f.elements.dose.value&&['mg','mcg','IU','mEq','unit'].includes(v.unit))f.elements.doseUnit.value=v.unit;
