   if(action==='save-calculation'){if(!carry||!sameCase(item,carry.patient))throw Error('계산 결과와 진료 건의 환자가 다릅니다.');return modal('마취 계산 초안 연결',`<pre>${esc(carry.summary)}</pre><label><input type="checkbox" name="confirm" required>동일 환자·체중·종·선택한 약물과 용량을 확인했습니다.</label>`,f=>event('calculation',{patientId:item.patient_id,caseId:item.id,calculator:carry.calculator,summary:carry.summary,species:carry.species,weight:carry.weight,confirm:f.elements.confirm.checked}));}
