  function deletedView(){const d=active().body.deleted;return `<section class="cl-card"><h4>삭제한 진료 건</h4><p>${fmtDate(d.at)} · ${esc(memberName(d.by))}</p><p>사유: ${esc(d.reason)}</p><p>기존 기록을 보관하고 있습니다. 진료 건을 복원하면 다시 기록할 수 있습니다.</p></section>${history()}`;}
  function identityCard(item){return `<section class="cl-identity"><div><b>${item.patient_id?'등록 환자 연결됨':'빠른 진료 · 보호자 등록 없음'}</b><p>${esc(item.body.title)}${item.body.quickPatient?.chartNumber?' · 차트 '+esc(item.body.quickPatient.chartNumber):''} · ${fmtDate(item.created_at)} · 식별 ${esc(item.id.slice(-6))}</p>${careTeamMarkup(item.body.careTeam)}</div><div class="cl-actions">${medical()&&item.status!=='closed'&&!item.body.deleted?button('care-team','CC·담당자 수정'):''}${medical()&&item.status!=='closed'?button('weight',item.body.weight?'체중 수정':'체중 입력'):''}${!item.patient_id&&!item.body.deleted&&medical()?button('link-patient','등록 환자와 연결'):''}${medical()?(item.body.deleted?button('restore-case','진료 건 복원'):button('delete-case','진료 건 삭제','class="cl-danger"')):''}</div></section>`;}
  function pickerMarkup(){return '<label>등록 환자 검색<input data-cl-patient-query maxlength="80" placeholder="환자명·보호자명·전화번호"></label><button type="button" data-cl-patient-search>검색</button><div data-cl-patient-results role="status"></div><p data-cl-picked></p>';}
  function bindPicker(f,onPick){let request=0;const query=f.querySelector('[data-cl-patient-query]'),out=f.querySelector('[data-cl-patient-results]'),context=scope;const search=async()=>{const q=query.value.trim();if(!q){out.textContent='검색어를 입력해주세요.';return;}const n=++request;out.textContent='검색 중…';try{const r=await a.request('/patient-directory?q='+encodeURIComponent(q)+'&active=active&pageSize=20');if(!current(context)||n!==request||!dialog?.contains(f))return;out.innerHTML=(r.patients||[]).map(p=>`<button type="button" data-cl-pick="${esc(p.id)}"><b>${esc(p.name)}</b> · ${esc(p.species==='dog'?'개':p.species==='cat'?'고양이':'종 미확인')} · 보호자 ${esc(p.guardianName||'미입력')}${p.guardianPhoneLast4?' · 연락처 끝 '+esc(p.guardianPhoneLast4):''}</button>`).join('')||'<p>일치하는 등록 환자가 없습니다. 빠른 입력으로 시작할 수 있습니다.</p>';if(r.pagination?.total>20)out.insertAdjacentHTML('beforeend','<p>결과가 많습니다. 검색어를 더 구체적으로 입력해주세요.</p>');out.querySelectorAll('[data-cl-pick]').forEach(btn=>btn.onclick=()=>{onPick(r.patients.find(p=>p.id===btn.dataset.clPick));dirty=true;});}catch(e){if(current(context)&&n===request&&dialog?.contains(f))out.textContent=e.message||'검색하지 못했습니다.';}};f.querySelector('[data-cl-patient-search]').onclick=search;query.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();void search();}};}
  function startCase(admitRoom){const contextPatient=selectedPatient();let picked=carry?.patient?.id?carry.patient:contextPatient?.id?contextPatient:a.patient()?.id?a.patient():null;modal(admitRoom?admitRoom.name+' · 입원 환자 등록':'새 진료 시작',`<div class="cl-start-modes" role="group" aria-label="진료 시작 방식"><button type="button" data-cl-mode="quick">빠른 입력</button><button type="button" data-cl-mode="registered">등록 환자 선택</button></div><section data-cl-quick><p class="cl-help">보호자 등록 없이 병원에 저장됩니다. 같은 이름이어도 별도의 진료 건으로 관리합니다.</p><div class="cl-form-grid">${input('quickName','환자명 · 차트번호와 둘 중 하나')}${input('chartNumber','차트번호 · 선택')}</div></section><section data-cl-registered hidden>${pickerMarkup()}</section><div class="cl-form-grid">${select('kind','진료 유형',Object.entries(kindNames),tab==='surgery'?'surgery':tab==='safety'?'consult':'admission')}${select('species','대상 동물',[['','선택'],['dog','개'],['cat','고양이']])}${input('weight','확인한 체중 · kg · 선택','','number')}</div>${careTeamFields()}<p class="cl-help">체중은 나중에 입력할 수 있습니다. 체중이 필요한 계산 전에는 반드시 확인해주세요.</p><details><summary>진료명·위치·주의사항 · 선택</summary>${input('title','진료·수술명')}${input('location','입원 위치·수술실')}${area('note','주요 진단·주의사항')}</details>`,async f=>{const v=formValues(f),registered=f.dataset.mode==='registered';if(registered&&!picked?.id)throw Error('등록 환자를 검색해 선택해주세요.');if(!registered&&!v.quickName.trim()&&!v.chartNumber.trim())throw Error('환자명 또는 차트번호를 입력해주세요.');const body={...(admitRoom?{roomId:admitRoom.id,roomRevision:admitRoom.revision}:{}),kind:admitRoom?'admission':v.kind,species:v.species,weight:v.weight===''?null:Number(v.weight),title:v.title,location:v.location,note:v.note,chiefComplaint:v.chiefComplaint,veterinarianId:v.veterinarianId,technicianId:v.technicianId,requestKey:f.dataset.clRequestKey,...(registered?{patientId:picked.id}:{quickPatient:{name:v.quickName,chartNumber:v.chartNumber}})};const r=await api('/cases','POST',body);selected=r.id;selectedRoom=admitRoom?.id||'';deleted=false;closed=false;carry=null;a.consume?.();});if(!dialog)return;const f=dialog.querySelector('form');f.elements.chiefComplaint.maxLength=500;const showPicked=()=>{f.querySelector('[data-cl-picked]').textContent=picked?'선택: '+picked.name+' · '+(picked.species==='dog'?'개':picked.species==='cat'?'고양이':'종 확인 필요')+(picked.guardianName?' · 보호자 '+picked.guardianName:''):'검색 결과에서 환자를 선택해주세요.';if(picked){f.elements.species.value=['dog','cat'].includes(picked.species)?picked.species:'';f.elements.weight.value=picked.weight||'';}};const setMode=mode=>{f.dataset.mode=mode;f.querySelector('[data-cl-quick]').hidden=mode!=='quick';f.querySelector('[data-cl-registered]').hidden=mode!=='registered';f.querySelectorAll('[data-cl-mode]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.clMode===mode)));f.elements.species.value='';f.elements.weight.value='';if(mode==='registered')showPicked();};f.querySelectorAll('[data-cl-mode]').forEach(b=>b.onclick=()=>{setMode(b.dataset.clMode);dirty=true;});bindPicker(f,p=>{picked=p;showPicked();});setMode(admitRoom?'quick':picked?'registered':'quick');if(admitRoom){f.elements.kind.value='admission';f.elements.kind.disabled=true;f.elements.species.value=admitRoom.kind==='cat'?'cat':'dog';f.elements.location.value=admitRoom.name;}f.querySelector('[type=submit]').textContent=admitRoom?'입원 등록':'진료 시작';}
