  function stepFields(s,i){return `<fieldset data-cl-step><legend>단계 ${i+1}</legend><label>단계명<input data-step="title" value="${esc(s.title)}"></label><label>분류<select data-step="stage">${Object.entries(stageNames).map(([k,v])=>`<option value="${k}" ${k===s.stage?'selected':''}>${v}</option>`).join('')}</select></label><label>내용<textarea data-step="detail">${esc(s.detail)}</textarea></label><label>연결 계산기<select data-step="calculator"><option value="">없음</option>${Object.entries(calcNames).map(([k,v])=>`<option value="${k}" ${k===s.calculator?'selected':''}>${v}</option>`).join('')}</select></label><label>시작 후 예정 시간<input type="number" step="0.5" min="0" data-step="offsetHours" value="${esc(s.offsetHours)}"></label></fieldset>`;}
